#include <stdio.h>
#include <math.h>

#define MAX_OBSTACLES 100
#define EPS 1e-9

typedef struct {
    double x1, y1, x2, y2;
} Obstacle;

int n;
double v, X, Y;
Obstacle obstacles[MAX_OBSTACLES];

int is_point_inside_obstacle(double x, double y, Obstacle *obs) {
    return x >= obs->x1 - EPS && x <= obs->x2 + EPS && 
           y >= obs->y1 - EPS && y <= obs->y2 + EPS;
}

int line_intersects_obstacle(double x1, double y1, double x2, double y2, Obstacle *obs) {
    // Check if line segment from (x1,y1) to (x2,y2) intersects obstacle
    // We'll sample points along the line
    int steps = 1000;
    for (int i = 0; i <= steps; i++) {
        double t = (double)i / steps;
        double x = x1 + (x2 - x1) * t;
        double y = y1 + (y2 - y1) * t;
        if (is_point_inside_obstacle(x, y, obs)) {
            return 1;
        }
    }
    return 0;
}

int can_drop(double theta) {
    double g = 9.8;
    double cos_theta = cos(theta);
    double sin_theta = sin(theta);

    // Check if we can reach x = X
    // Parabola: y = x*tan(theta) - g*x^2/(2*v^2*cos^2(theta))
    double y_bird = X * tan(theta) - g * X * X / (2 * v * v * cos_theta * cos_theta);

    if (y_bird <= Y + EPS) {
        return 0;  // Bird is not above the pig
    }

    // Check bird's trajectory from (0,0) to (X, y_bird)
    int steps = 1000;
    for (int i = 0; i <= steps; i++) {
        double t = (double)i / steps;
        double x = X * t;
        double y = x * tan(theta) - g * x * x / (2 * v * v * cos_theta * cos_theta);

        if (y < -EPS) {
            return 0;  // Bird went below ground
        }

        // Check if this point is inside any obstacle
        for (int j = 0; j < n; j++) {
            if (is_point_inside_obstacle(x, y, &obstacles[j])) {
                return 0;
            }
        }
    }

    // Check egg's vertical fall from (X, y_bird) to (X, Y)
    for (int i = 0; i <= steps; i++) {
        double t = (double)i / steps;
        double y = y_bird + (Y - y_bird) * t;
        double x = X;

        for (int j = 0; j < n; j++) {
            if (is_point_inside_obstacle(x, y, &obstacles[j])) {
                return 0;
            }
        }
    }

    return 1;
}

