#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define EPS 1e-10

typedef struct {
    double l, b, r, t;
} Rect;

static double sq(double x) { return x * x; }

int main(void) {
    int N;
    double V, X, Y;

    if (scanf("%d %lf %lf %lf", &N, &V, &X, &Y) != 4) return 0;

    Rect *obs = (Rect *)malloc(sizeof(Rect) * N);
    for (int i = 0; i < N; i++) {
        scanf("%lf %lf %lf %lf", &obs[i].l, &obs[i].b, &obs[i].r, &obs[i].t);
    }

    const double g = 9.8;

    /* Candidate x-positions where the bird may drop the egg:
       directly above the pig, or above vertical sides of obstacles.
       This is sufficient because feasibility changes only when crossing
       such x-coordinates. */
    double *cand = (double *)malloc(sizeof(double) * (2 * N + 1));
    int m = 0;
    cand[m++] = X;
    for (int i = 0; i < N; i++) {
        cand[m++] = obs[i].l;
        cand[m++] = obs[i].r;
    }

    int ok = 0;

    for (int ci = 0; ci < m && !ok; ci++) {
        double x = cand[ci];

        /* To hit the pig by vertical drop, bird must pass through (x, Y)
           and x must be at or to the right of pig. */
        if (x + EPS < X) continue;
        if (x < -EPS) continue;

        /* Solve projectile equation for reaching (x, Y):
           y = x*tan(theta) - g*x^2/(2*V^2)*(1+tan^2(theta))
           => quadratic in p = tan(theta)
        */
        double a = g * x * x;
        double b = -2.0 * V * V * x;
        double c = 2.0 * V * V * Y + g * x * x;

        /* More numerically stable via discriminant from standard form:
           g^2 x^4 - 4a'c' ... simplified:
           D = V^4 - g*(g*x^2 + 2*Y*V^2)
        */
        double D = V * V * V * V - g * (g * x * x + 2.0 * Y * V * V);
        if (D < -EPS) continue;
        if (D < 0) D = 0;

        double sqrtD = sqrt(D);

        /* Two possible trajectories */
        for (int k = 0; k < 2 && !ok; k++) {
            double p;
            if (fabs(x) < EPS) {
                /* x = 0: only possible if Y == 0 */
                if (fabs(Y) > EPS) continue;
                p = 0.0;
            } else {
                p = (V * V + (k == 0 ? sqrtD : -sqrtD)) / (g * x);
            }

            /* Check the bird's path until drop point x */
            int bad = 0;
            for (int i = 0; i < N && !bad; i++) {
                /* If obstacle is completely to the right of drop point,
                   irrelevant for flight before drop. */
                if (obs[i].l >= x - EPS) continue;

                /* Check intersection of parabola with obstacle rectangle
                   over horizontal interval [max(0,l), min(r,x)] */
                double L = obs[i].l;
                double R = obs[i].r;
                if (R < 0) continue;
                if (L < 0) L = 0;
                if (R > x) R = x;
                if (L > R + EPS) continue;

                /* y(t) = xx*p - g*xx^2/(2V^2)*(1+p^2), concave down.
                   On [L,R], maximum at vertex or endpoints, minimum at endpoints. */
                double A = -g * (1.0 + p * p) / (2.0 * V * V);
                double B = p;

                double yL = A * L * L + B * L;
                double yR = A * R * R + B * R;
                double ymin = yL < yR ? yL : yR;
                double ymax = yL > yR ? yL : yR;

                double xv = -B / (2.0 * A); /* vertex x */
                if (xv >= L - EPS && xv <= R + EPS) {
                    double yv = A * xv * xv + B * xv;
                    if (yv > ymax) ymax = yv;
                }

                /* Intersects rectangle iff vertical ranges overlap */
                if (!(ymax < obs[i].b - EPS || ymin > obs[i].t + EPS)) {
                    bad = 1;
                }
            }
            if (bad) continue;

            /* Check vertical egg drop from (x, Y) downward at x = constant:
               any obstacle containing x and spanning above Y blocks it. */
            for (int i = 0; i < N && !bad; i++) {
                if (obs[i].l - EPS <= X && X <= obs[i].r + EPS) {
                    /* Actually drop occurs at x, not X */
                }
            }

            for (int i = 0; i < N && !bad; i++) {
                if (obs[i].l - EPS <= x && x <= obs[i].r + EPS) {
                    /* Vertical segment from (x, Y) to pig at (X,Y) is just downward from bird's
                       actual drop point height equal to Y? No: bird passes through (x,Y), so egg
                       starts at height Y and pig is also at height Y only if x==X.
                       Since to hit pig after vertical drop, bird must drop when horizontally above pig.
                       Therefore only x==X is physically valid. */
                    ;
                }
            }

            /* Physical condition for vertical drop to hit pig: must be directly above pig. */
            if (fabs(x - X) > EPS) continue;

            /* Need the bird to be able to reach (X,Y); dropping there hits pig immediately.
               No obstacle may contain point (X,Y), but pig is assumed not inside obstacle.
            */
            ok = 1;
        }
    }

    printf("%s\n", ok ? "Yes" : "No");

    free(obs);
    free(cand);
    return 0;
}

