#include <bits/stdc++.h>
using namespace std;

const double g = 9.8;
const double EPS = 1e-9;

struct Obstacle {
    double x1, y1, x2, y2;
};

bool canReach(double v, double X, double Y, const vector<Obstacle>& obstacles) {
    // Binary search on angle
    double lo = 0, hi = M_PI / 2;

    for (int iter = 0; iter < 200; iter++) {
        double mid = (lo + hi) / 2;
        double theta = mid;

        double cosT = cos(theta);
        double sinT = sin(theta);

        if (cosT < EPS) {
            lo = mid;
            continue;
        }

        double t = X / (v * cosT);
        double y_bird = v * sinT * t - 0.5 * g * t * t;

        if (y_bird < Y - EPS) {
            lo = mid;
            continue;
        }

        // Check if bird's trajectory and egg drop are clear
        bool valid = true;

        // Check bird's trajectory
        for (int steps = 0; steps <= 1000; steps++) {
            double t_check = t * steps / 1000.0;
            double x_check = v * cosT * t_check;
            double y_check = v * sinT * t_check - 0.5 * g * t_check * t_check;

            if (y_check < -EPS) {
                valid = false;
                break;
            }

            // Check if this point is inside any obstacle
            for (const auto& obs : obstacles) {
                if (x_check >= obs.x1 - EPS && x_check <= obs.x2 + EPS &&
                    y_check >= obs.y1 - EPS && y_check <= obs.y2 + EPS) {
                    valid = false;
                    break;
                }
            }
            if (!valid) break;
        }

        if (!valid) {
            lo = mid;
            continue;
        }

        // Check egg drop path (vertical line from (X, y_bird) to (X, Y))
        for (const auto& obs : obstacles) {
            // Check if vertical line intersects obstacle
            if (X >= obs.x1 - EPS && X <= obs.x2 + EPS) {
                double top = min(y_bird, Y);
                double bottom = max(y_bird, Y);
                if (top + EPS < obs.y2 && bottom - EPS > obs.y1) {
                    valid = false;
                    break;
                }
            }
        }

        if (valid) {
            hi = mid;
        } else {
            lo = mid;
        }
    }

    // Check if the final angle works
    double theta = (lo + hi) / 2;
    double cosT = cos(theta);
    if (cosT < EPS) return false;

    double t = X / (v * cosT);
    double y_bird = v * sin(theta) * t - 0.5 * g * t * t;

    return y_bird >= Y - EPS;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    double v, X, Y;
    cin >> N >> v >> X >> Y;

    vector<Obstacle> obstacles(N);
    for (int i = 0; i < N; i++) {
        cin >> obstacles[i].x1 >> obstacles[i].y1 >> obstacles[i].x2 >> obstacles[i].y2;
    }

    if (canReach(v, X, Y, obstacles)) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const double g = 9.8;
static const double EPS = 1e-10;

struct Rect {
    double l, b, r, t;
};

double calcY(double vx, double vy, double x) {
    double t = x / vx;
    return vy * t - 0.5 * g * t * t;
}

bool hitSegment(double x1, double y1, double x2, double y2, double px, double py) {
    // Check whether point (px,py) lies on segment between (x1,y1) and (x2,y2)
    double cross = (x2 - x1) * (py - y1) - (y2 - y1) * (px - x1);
    if (fabs(cross) > 1e-8) return false;
    double dot = (px - x1) * (px - x2) + (py - y1) * (py - y2);
    return dot <= 1e-8;
}

bool solveCase(int N, double V, double X, double Y, const vector<Rect>& obs) {
    // Candidate dropping x-coordinates:
    // - exactly at pig x = X
    // - left/right edges of obstacles, because feasibility changes there
    vector<double> cand;
    cand.push_back(X);
    for (auto &rc : obs) {
        cand.push_back(rc.l);
        cand.push_back(rc.r);
    }

    for (double dx : cand) {
        if (dx < X - EPS) continue; // must be able to drop vertically onto pig

        // Need trajectory passing through (dx, Y') with Y' >= Y.
        // For minimal requirement, check passing through (dx, Y).
        // If bird can reach higher, dropping works too, but for obstacle avoidance
        // it suffices to test the trajectory that passes through (dx, Y), since
        // any larger height only raises the path before dx.
        //
        // Solve for vx^2 from:
        // Y = dx * tan(theta) - g*dx^2/(2*V^2*cos^2(theta))
        // Let p = vx^2. Using vy^2 = V^2 - p and t = dx/sqrt(p):
        // Y = dx*sqrt(V^2-p)/sqrt(p) - g*dx^2/(2p)
        //
        // Standard quadratic in tan(theta):
        // a*T^2 - dx*T + (a+Y)=0, where a=g*dx^2/(2V^2)
        double a = g * dx * dx / (2.0 * V * V);
        double D = dx * dx - 4.0 * a * (a + Y);
        if (D < -EPS) continue;
        D = max(0.0, D);

        vector<double> tans;
        tans.push_back((dx + sqrt(D)) / (2.0 * a));
        if (D > EPS) tans.push_back((dx - sqrt(D)) / (2.0 * a));

        for (double T : tans) {
            double cos2 = 1.0 / (1.0 + T * T);
            double sin2 = 1.0 - cos2;
            double vx = V * sqrt(cos2);
            double vy = V * sqrt(sin2);
            if (T < 0) continue;
            vy = vx * T;

            // Bird reaches x=dx at height exactly Y.
            // Then it can drop vertically; need no obstacle collision:
            // 1) trajectory from x=0 to x=dx
            // 2) vertical fall at x=dx from y=Y downward to pig y=Y (degenerate),
            //    actually pig is at (X,Y), so after drop it falls vertically at x=dx
            //    and can only hit pig if dx==X? No: egg is dropped vertically, so it
            //    must be dropped when bird is exactly above pig, i.e. dx = X.
            //
            // However known formulation of this problem allows bird to hit pig by
            // passing through (X,Y) directly OR via vertical drop after x>=X with pig
            // on same vertical line only if dx==X. Therefore only x=X is meaningful.
            // Still, obstacle-edge candidates are used in the original approach by
            // targeting obstacle corners. We handle direct passing through target and
            // require x=X for the drop.
            if (fabs(dx - X) > 1e-8) continue;

            bool ok = true;

            // Check if pig is hit before landing: trajectory must pass through (X,Y)
            // and not be blocked by obstacles.
            for (auto &rc : obs) {
                // If start point inside obstacle boundary path impossible
                // Check vertical sides x=l,r if within [0,X]
                for (double xside : {rc.l, rc.r}) {
                    if (xside < -EPS || xside > X + EPS) continue;
                    double y = calcY(vx, vy, xside);
                    if (y > rc.b + EPS && y < rc.t - EPS) ok = false;
                }

                // Check top/bottom edges: whether parabola intersects them over overlap
                double xl = max(0.0, rc.l);
                double xr = min(X, rc.r);
                if (xl <= xr + EPS) {
                    // Since parabola is concave, max on interval at vertex or ends.
                    double xv = vx * vy / g;
                    vector<double> xs = {xl, xr};
                    if (xv >= xl - EPS && xv <= xr + EPS) xs.push_back(xv);

                    double ymin = 1e100, ymax = -1e100;
                    for (double xx : xs) {
                        double yy = calcY(vx, vy, xx);
                        ymin = min(ymin, yy);
                        ymax = max(ymax, yy);
                    }

                    if (ymax > rc.b + EPS && ymin < rc.t - EPS) {
                        // Need actual overlap with rectangle interior.
                        // Sample critical points sufficient for quadratic against constants.
                        // Check if there exists x in [xl,xr] with y in (b,t).
                        auto f = [&](double xx){ return calcY(vx, vy, xx); };

                        // Solve y=b and y=t
                        auto rootsFor = [&](double yy) {
                            // -g/(2vx^2)x^2 + (vy/vx)x - yy = 0
                            double A = -g / (2.0 * vx * vx);
                            double B = vy / vx;
                            double C = -yy;
                            double DD = B * B - 4 * A * C;
                            vector<double> rt;
                            if (DD < -EPS) return rt;
                            DD = max(0.0, DD);
                            rt.push_back((-B + sqrt(DD)) / (2 * A));
                            if (DD > EPS) rt.push_back((-B - sqrt(DD)) / (2 * A));
                            return rt;
                        };

                        vector<double> pts = {xl, xr};
                        if (xv >= xl - EPS && xv <= xr + EPS) pts.push_back(xv);
                        for (double rr : rootsFor(rc.b))
                            if (rr >= xl - EPS && rr <= xr + EPS) pts.push_back(rr);
                        for (double rr : rootsFor(rc.t))
                            if (rr >= xl - EPS && rr <= xr + EPS) pts.push_back(rr);

                        sort(pts.begin(), pts.end());
                        pts.erase(unique(pts.begin(), pts.end(), [](double a, double b){
                            return fabs(a - b) < 1e-8;
                        }), pts.end());

                        for (int i = 0; i + 1 < (int)pts.size(); i++) {
                            double mid = (pts[i] + pts[i + 1]) * 0.5;
                            if (mid < xl - EPS || mid > xr + EPS) continue;
                            double yy = f(mid);
                            if (yy > rc.b + EPS && yy < rc.t - EPS) {
                                ok = false;
                                break;
                            }
                        }
                    }
                }

                if (!ok) break;
            }

            if (ok) return true;
        }
    }

    return false;
}

