    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    double V, X, Y;
    cin >> N >> V >> X >> Y;
    vector<Rect> obs(N);
    for (int i = 0; i < N; i++) {
        double x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        obs[i] = {min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)};
