        int[] y2 = new int[N];

        for (int i = 0; i < N; i++) {
            x1[i] = sc.nextInt();
            y1[i] = sc.nextInt();
            x2[i] = sc.nextInt();
            y2[i] = sc.nextInt();
        }

        double g = 9.8;

        for (double theta = 0; theta <= Math.PI / 2; theta += 0.0001) {
            double vx = v * Math.cos(theta);
            double vy = v * Math.sin(theta);

            double t = X / vx;
            double birdY = vy * t - 0.5 * g * t * t;

            if (birdY < Y) continue;

            double eggDropX = X;
            double eggDropY = birdY;

            boolean hitObstacle = false;
            for (int i = 0; i < N; i++) {
                if (isInside(eggDropX, eggDropY, x1[i], y1[i], x2[i], y2[i])) {
                    hitObstacle = true;
                    break;
                }
            }

            if (!hitObstacle) {
                boolean pathBlocked = false;
                double dt = 0.01;
                for (double tt = 0; tt <= t; tt += dt) {
                    double px = vx * tt;
                    double py = vy * tt - 0.5 * g * tt * tt;
                    for (int i = 0; i < N; i++) {
                        if (isInside(px, py, x1[i], y1[i], x2[i], y2[i])) {
                            pathBlocked = true;
                            break;
                        }
                    }
                    if (pathBlocked) break;
                }

                if (!pathBlocked) {
                    System.out.println("Yes");
                    return;
                }
            }
        }

        System.out.println("No");
    }

    static boolean isInside(double x, double y, int x1, int y1, int x2, int y2) {
        return x >= x1 && x <= x2 && y >= y1 && y <= y2;
    }
}

