                    // check if min/max of parabola in [xlo,xhi] intersects [oy1,oy2]
                    double A = -g*(1+t*t)/(2*v0*v0);
                    double B = t;
                    double xpeak = -B/(2*A);
                    double[] xs = {xlo, xhi};
