                    double ymin = Double.MAX_VALUE, ymax = -Double.MAX_VALUE;
                    for (double x : xs) { double yy = B*x+A*x*x; ymin=Math.min(ymin,yy); ymax=Math.max(ymax,yy); }
                    if (ymax >= oy1 && ymin <= oy2) { ok = false; break; }
                }
                // Check vertical drop at x=pigX from birdY to pigY
                if (pigX >= ox1 && pigX <= ox2 && pigY <= oy2 && birdY >= oy1) { ok = false; break; }
