import java.io.*;
import java.util.*;

/*
 * Angry Birds (white bird with egg bomb)
 *
 * We need to determine whether there exists a valid parabolic trajectory of the bird
 * starting from (0,0) with speed V, such that:
 *   - the bird reaches some point directly above the pig, i.e. x = X and y >= Y
 *   - then it can drop an egg vertically onto the pig
 *   - neither the bird's flight path nor the vertical egg path intersects any obstacle
 *
 * Obstacles are axis-aligned rectangles.
 *
 * Standard projectile equation:
 *   y = x*tan(theta) - g*x^2 / (2*V^2*cos^2(theta))
 *
 * For a chosen passing point (x, y), solving for theta is equivalent to solving in t = tan(theta):
 *   A t^2 - x t + (A + y) = 0
 * where A = g*x^2 / (2*V^2)
 *
 * This problem can be solved by considering candidate points (X, Y) and rectangle top corners:
 * if a feasible trajectory exists, one can lower the drop point until it is either exactly the pig
 * or just touches the top of some obstacle. So it suffices to test:
 *   - (X, Y)
 *   - (X, topY of each obstacle whose horizontal span covers X and topY >= Y)
 *
 * For each candidate drop point (X, dropY), find up to two launch angles, then verify:
 *   1) bird path does not intersect any rectangle before x = X
 *   2) vertical segment from (X, dropY) down to (X, Y) does not intersect any rectangle
 *
 * We treat touching an obstacle as collision.
 */
public class Main {
    static final double G = 9.8;
    static final double EPS = 1e-9;

    static class Rect {
        double x1, y1, x2, y2; // normalized: x1 <= x2, y1 <= y2
        Rect(double a, double b, double c, double d) {
            x1 = Math.min(a, c);
            x2 = Math.max(a, c);
            y1 = Math.min(b, d);
            y2 = Math.max(b, d);
        }
    }

    static int N;
    static double V, X, Y;
    static Rect[] rects;

    static double f(double x, double tanT) {
        return x * tanT - G * x * x * (1.0 + tanT * tanT) / (2.0 * V * V);
    }

    static boolean intersectsVerticalDrop(double dropY) {
        // vertical segment at x = X from y = Y to y = dropY
        double lo = Math.min(Y, dropY);
        double hi = Math.max(Y, dropY);
        for (Rect r : rects) {
            if (r.x1 - EPS <= X && X <= r.x2 + EPS) {
                if (Math.max(lo, r.y1) <= Math.min(hi, r.y2) + EPS) {
                    return true;
                }
            }
        }
        return false;
    }

    static boolean pathHitsRect(double tanT, Rect r) {
        // Only relevant for x-range before reaching X
        double l = Math.max(0.0, r.x1);
        double rr = Math.min(X, r.x2);
        if (l > rr + EPS) return false;

        // Trajectory is concave down, so on interval [l, rr]:
        // max occurs at vertex if inside, else at endpoint.
        // min occurs at one of endpoints.
        double yL = f(l, tanT);
        double yR = f(rr, tanT);

        double minY = Math.min(yL, yR);
        double maxY = Math.max(yL, yR);

        // vertex x-coordinate for y = x*t - a*x^2*(1+t^2), derivative zero:
        // t - g*x*(1+t^2)/V^2 = 0 => x = t*V^2 / (g*(1+t^2))
        double xv = tanT * V * V / (G * (1.0 + tanT * tanT));
        if (l - EPS <= xv && xv <= rr + EPS) {
            maxY = Math.max(maxY, f(xv, tanT));
        }

        // If vertical ranges overlap, since rectangle spans all x in [l,rr], need more careful check.
        // Because parabola is continuous, if its y on interval overlaps rectangle's y-range,
        // there exists some x where it enters/touches the rectangle.
        if (maxY < r.y1 - EPS || minY > r.y2 + EPS) return false;
        return true;
    }

    static boolean can(double dropY) {
        if (dropY + EPS < Y) return false;
        if (intersectsVerticalDrop(dropY)) return false;

        double x = X, y = dropY;
        double A = G * x * x / (2.0 * V * V);

        // Solve A t^2 - x t + (A + y) = 0
        double D = x * x - 4.0 * A * (A + y);
        if (D < -EPS) return false;
        if (D < 0) D = 0;

        double sqrtD = Math.sqrt(D);
        double[] tans = new double[2];
        int cnt = 0;

        tans[cnt++] = (x + sqrtD) / (2.0 * A);
        if (sqrtD > EPS) tans[cnt++] = (x - sqrtD) / (2.0 * A);

        for (int i = 0; i < cnt; i++) {
            double tanT = tans[i];
            boolean ok = true;
            for (Rect r : rects) {
                if (pathHitsRect(tanT, r)) {
                    ok = false;
                    break;
                }
            }
            if (ok) return true;
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = fs.nextInt();
        V = fs.nextDouble();
        X = fs.nextDouble();
        Y = fs.nextDouble();

        rects = new Rect[N];
        for (int i = 0; i < N; i++) {
            double x1 = fs.nextDouble();
            double y1 = fs.nextDouble();
            double x2 = fs.nextDouble();
            double y2 = fs.nextDouble();
            rects[i] = new Rect(x1, y1, x2, y2);
        }

        List<Double> candidates = new ArrayList<>();
        candidates.add(Y);

        for (Rect r : rects) {
            if (r.x1 - EPS <= X && X <= r.x2 + EPS && r.y2 + EPS >= Y) {
                candidates.add(r.y2);
            }
        }

        boolean ans = false;
        for (double dropY : candidates) {
            if (can(dropY)) {
                ans = true;
                break;
            }
        }

        System.out.println(ans ? "Yes" : "No");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}
